function validate([text]) {
  if (typeof text !== 'string' || text.length < 1 || text.length > 100) return 'text needs 1 to 100 characters.';
  if (!/^[a-z ]+$/.test(text)) return 'text may contain only lowercase letters and spaces.';
  if (!/[a-z]/.test(text)) return 'text must contain at least one word.';
  return null;
}

