function reorderSpaces(text) {
  // Collect words by hand, then hand out spaces one round at a time to every gap.
  const words = [];
  let current = '', spaces = 0;
  for (const ch of text + ' ') {
    if (ch === ' ') {
      if (current) words.push(current);
      current = '';
    } else current += ch;
  }
  for (const ch of text) if (ch === ' ') spaces++;
  const gaps = new Array(words.length - 1).fill(0);
  while (gaps.length > 0 && spaces >= gaps.length) {
    for (let i = 0; i < gaps.length; i++) gaps[i]++;
    spaces -= gaps.length;
  }
  let out = '';
  for (let i = 0; i < words.length; i++) {
    out += words[i];
    if (i < gaps.length) for (let k = 0; k < gaps[i]; k++) out += ' ';
  }
  for (let k = 0; k < spaces; k++) out += ' ';
  return out;
}

