function generate(rand, size) {
  const limit = size === 'large' ? 100 : 12;
  const maxWords = size === 'large' ? 1 + Math.floor(rand() * 20) : 1 + Math.floor(rand() * 4);
  const letters = size === 'large' ? 'abcdefghijklmnopqrstuvwxyz' : 'ab';
  const word = () => Array.from({ length: 1 + Math.floor(rand() * 4) }, () => letters[Math.floor(rand() * letters.length)]).join('');
  const blank = (least, most) => ' '.repeat(least + Math.floor(rand() * (most - least + 1)));
  const spread = size === 'large' ? 6 : 2;
  let text = blank(0, spread) + word();
  for (let w = 1; w < maxWords; w++) {
    const next = blank(1, spread) + word();
    if (text.length + next.length > limit) break;
    text += next;
  }
  const tail = blank(0, spread);
  if (text.length + tail.length <= limit) text += tail;
  return [text];
}
